package souther.runtime;

import java.util.List;
import java.util.Set;
import java.util.function.Function;

/** Set helpers the generated bytecode calls. A Set is unordered with no duplicates, compared by the
 *  elements' value equality (spec collections, ADR-0009). A {@code Set} value is a
 *  {@link PersistentHashSet} (CHAMP, structural sharing): every operation returns a fresh set that
 *  shares structure with its input in O(log n) and never mutates it. The language specifies no
 *  iteration order, and it is not first-seen order; two sets that are equal are not guaranteed to
 *  iterate in the same order, so neither a caller nor {@code toList} may depend on a particular one
 *  ({@link PersistentHashSet}). A boundary encode does not: it goes through {@link #toList} and is
 *  then put in the order the members' own external representations give
 *  ({@link Representations#sortedArray}), so the boundary's order is specified and this one is not.
 *  This class is Raoh-free; {@link #fromList}
 *  is also the dedup a Set decoder maps a list through, and keeps its exact {@code (List) -> Set}
 *  signature because a Set decoder resolves it by method handle. */
public final class Sets {

    private Sets() {}

    /** The empty set; its element type is fixed by context (the {@code Set.empty} built-in). */
    public static Set<?> empty() {
        return PersistentHashSet.empty();
    }

    public static <T> Set<T> singleton(T value) {
        return PersistentHashSet.ofSingle(value);
    }

    /** {@link #singleton(Object)}, hashing the element under {@code checkpoint}. */
    public static <T> Set<T> singleton(T value, WorkCheckpoint checkpoint) {
        return PersistentHashSet.<T>empty().with(value, checkpoint);
    }

    public static <T> Set<T> insert(T value, Set<T> s) {
        return insert(value, s, WorkCheckpoint.NONE);
    }

    /** {@link #insert(Object, Set)}, comparing elements under {@code checkpoint}. */
    public static <T> Set<T> insert(T value, Set<T> s, WorkCheckpoint checkpoint) {
        return PersistentHashSet.from(s, checkpoint).with(value, checkpoint);
    }

    /** {@code s} without {@code value}; {@code s} unchanged when absent. The {@code contains} probe
     *  returns the original set untouched when the value is absent, avoiding normalizing a still-JDK
     *  input set into a {@code PersistentHashSet} for a no-op removal. */
    public static <T> Set<T> remove(T value, Set<T> s) {
        return remove(value, s, WorkCheckpoint.NONE);
    }

    /** {@link #remove(Object, Set)}, comparing elements under {@code checkpoint}. */
    public static <T> Set<T> remove(T value, Set<T> s, WorkCheckpoint checkpoint) {
        if (!contains(value, s, checkpoint)) {
            return s;
        }
        return PersistentHashSet.from(s, checkpoint).without(value, checkpoint);
    }

    /** Whether {@code s} holds {@code value}, by the index {@code s} carries. Every set Souther
     *  builds — including the one a {@code Set} field decodes into — is indexed by the language
     *  ({@link Values}), so an amount is found at either scale. A {@code java.util.Set} handed in
     *  from Java carries Java's index and is answered by it, as a foreign collection is anywhere
     *  else (ADR-0085). */
    public static boolean contains(Object value, Set<?> s) {
        return contains(value, s, WorkCheckpoint.NONE);
    }

    /** {@link #contains(Object, Set)}, comparing elements under {@code checkpoint} where the set is
     *  one this runtime built; a set from outside answers by its own index, as it does without one. */
    public static boolean contains(Object value, Set<?> s, WorkCheckpoint checkpoint) {
        return s instanceof PersistentHashSet<?> ours ? ours.contains(value, checkpoint) : s.contains(value);
    }

    public static <T> Set<T> union(Set<T> a, Set<T> b) {
        return PersistentHashSet.union(a, b);
    }

    /** {@link #union(Set, Set)}, passing {@code checkpoint} once for each element. */
    public static <T> Set<T> union(Set<T> a, Set<T> b, WorkCheckpoint checkpoint) {
        return PersistentHashSet.union(a, b, checkpoint);
    }

    public static <T> Set<T> intersection(Set<T> a, Set<T> b) {
        return PersistentHashSet.intersect(a, b);
    }

    /** {@link #intersection(Set, Set)}, passing {@code checkpoint} once for each element. */
    public static <T> Set<T> intersection(Set<T> a, Set<T> b, WorkCheckpoint checkpoint) {
        return PersistentHashSet.intersect(a, b, checkpoint);
    }

    /** The elements of {@code a} that are not in {@code b}. */
    public static <T> Set<T> difference(Set<T> a, Set<T> b) {
        return PersistentHashSet.difference(a, b);
    }

    /** {@link #difference(Set, Set)}, passing {@code checkpoint} once for each element. */
    public static <T> Set<T> difference(Set<T> a, Set<T> b, WorkCheckpoint checkpoint) {
        return PersistentHashSet.difference(a, b, checkpoint);
    }

    /**
     * The elements of {@code xs} that one before them already is, by the elements' value equality:
     * each such value once, as it stands where it first repeats, in the order those repetitions
     * come. Empty where nothing repeats.
     *
     * <p>Two sets filled in place, each element looked up once in each set it reaches: a set built
     * up value by value through {@link #insert} would copy its path on every element.
     */
    public static <T> List<T> repeated(List<T> xs) {
        return repeated(xs, WorkCheckpoint.NONE);
    }

    /** {@link #repeated(List)}, passing {@code checkpoint} once for each element and comparing
     *  elements under it. */
    public static <T> List<T> repeated(List<T> xs, WorkCheckpoint checkpoint) {
        PersistentHashMap.Builder<T, Object> seen = new PersistentHashMap.Builder<>(checkpoint);
        PersistentHashMap.Builder<T, Object> reported = new PersistentHashMap.Builder<>(checkpoint);
        PersistentVector.Builder<T> out = new PersistentVector.Builder<>();
        for (T x : xs) {
            checkpoint.pass();
            int before = seen.size();
            seen.set(x, Boolean.TRUE);
            if (seen.size() == before) {
                int named = reported.size();
                reported.set(x, Boolean.TRUE);
                if (reported.size() != named) {
                    out.add(x);
                }
            }
        }
        return out.build();
    }

    public static boolean isEmpty(Set<?> s) {
        return s.isEmpty();
    }

    public static long size(Set<?> s) {
        return s.size();
    }

    public static <T> List<T> toList(Set<T> s) {
        return PersistentVector.from(s);
    }

    /** {@link #toList(Set)}, passing {@code checkpoint} once for each element. */
    public static <T> List<T> toList(Set<T> s, WorkCheckpoint checkpoint) {
        return PersistentVector.from(s, checkpoint);
    }

    /** A set from a list, dropping duplicates. Also the map a derived Set decoder applies to the list
     *  it decodes. */
    public static <T> Set<T> fromList(List<T> xs) {
        return PersistentHashSet.from(xs);
    }

    /** {@link #fromList(List)}, passing {@code checkpoint} once for each element and comparing
     *  elements under it. */
    public static <T> Set<T> fromList(List<T> xs, WorkCheckpoint checkpoint) {
        return PersistentHashSet.from(xs, checkpoint);
    }

    /** Every element through {@code f}, deduplicating the result the way a set must — the
     *  codegen-internal counterpart to {@link Lists#map} for a crossing's canonicalization
     *  ({@code CanonicalizeAtCrossing}): two elements that canonicalize to the one value are one
     *  member, same as {@link #fromList} already collapses two canonically equivalent decoded
     *  strings into one. */
    public static Set<Object> map(Function<Object, Object> f, Set<?> s) {
        return map(f, s, WorkCheckpoint.NONE);
    }

    /** {@link #map(Function, Set)}, passing {@code checkpoint} once for each
     *  element. */
    public static Set<Object> map(Function<Object, Object> f, Set<?> s,
                                  WorkCheckpoint checkpoint) {
        return fromList(Lists.map(f, toList(s, checkpoint), checkpoint), checkpoint);
    }
}
